interface Animal {
    String sound();
}

class Dog implements Animal {
    public String sound() { return "Woof"; }
}

class Cat implements Animal {
    public String sound() { return "Meow"; }
}

public class Main {
    public static void main(String[] args) {
        Animal a1 = new Dog();
        Animal a2 = new Cat();
        System.out.println(a1.sound() + " " + a2.sound());
    }
}

interface Vehicle {
    default String horn() { return "Generic beep"; }
}

class Car implements Vehicle {
    public String horn() { return "Honk honk!"; }
}

class Bicycle implements Vehicle { }

public class Main {
    public static void main(String[] args) {
        Vehicle v1 = new Car();
        Vehicle v2 = new Bicycle();
        System.out.println(v1.horn() + " " + v2.horn());
    }
}

interface Shape {
    double area();
}

class Circle implements Shape {
    private double r;
    Circle(double r) { this.r = r; }
    public double area() { return Math.PI * r * r; }
}

class Rectangle implements Shape {
    private double w, h;
    Rectangle(double w, double h) { this.w = w; this.h = h; }
    public double area() { return w * h; }
}

public class Main {
    static void printArea(Shape s) {
        System.out.printf("%.1f ", s.area());
    }

    public static void main(String[] args) {
        printArea(new Circle(2));
        printArea(new Rectangle(3, 4));
    }
}

interface Speaker {
    String speak();
}

class Human implements Speaker {
    public String speak() { return "Hello"; }
}

class Robot implements Speaker {
    public String speak() { return "Beep boop"; }
}

class Parrot implements Speaker {
    public String speak() { return "Hello"; }
}

public class Main {
    public static void main(String[] args) {
        Speaker[] speakers = { new Human(), new Robot(), new Parrot() };
        for (Speaker s : speakers) {
            if (s.speak().equals("Hello")) {
                System.out.print("Y ");
            } else {
                System.out.print("N ");
            }
        }
    }
}

import java.util.Arrays;

class Person implements Comparable<Person> {
    String name;
    int age;
    Person(String name, int age) { this.name = name; this.age = age; }
    public int compareTo(Person other) {
        return Integer.compare(this.age, other.age);
    }
    public String toString() { return name + ":" + age; }
}

public class Main {
    public static void main(String[] args) {
        Person[] people = {
            new Person("Alice", 30),
            new Person("Bob", 25),
            new Person("Charlie", 35)
        };
        Arrays.sort(people);
        System.out.println(Arrays.toString(people));
    }
}

interface Flyable { }
interface Swimmable { }

class Duck implements Flyable, Swimmable { }
class Plane implements Flyable { }

public class Main {
    public static void main(String[] args) {
        Flyable f = new Duck();
        System.out.println(f instanceof Flyable);
        System.out.println(f instanceof Swimmable);
        System.out.println(f instanceof Plane);
    }
}

import java.util.ArrayList;
import java.util.List;

interface Drawable {
    void draw();
}

class Circle implements Drawable {
    public void draw() { System.out.print("Circle "); }
}

class Square implements Drawable {
    public void draw() { System.out.print("Square "); }
}

public class Main {
    public static void main(String[] args) {
        List<Drawable> shapes = new ArrayList<>();
        shapes.add(new Circle());
        shapes.add(new Square());
        shapes.add(new Circle());
        for (Drawable d : shapes) {
            d.draw();
        }
    }
}

interface A {
    default String greet() { return "Hi from A"; }
}

interface B {
    default String greet() { return "Hi from B"; }
}

class MyClass implements A, B { }

interface Playable {
    void play();
}

class Video implements Playable {
    public void play() { System.out.println("Playing video"); }
    public void stop() { System.out.println("Stopped"); }
}

public class Main {
    public static void main(String[] args) {
        Playable p = new Video();
        p.play();
        p.stop();
    }
}

interface Vehicle {
    void move();
}

class Car implements Vehicle {
    public void move() { System.out.print("Driving "); }
    void refuel() { System.out.print("Refueling "); }
}

public class Main {
    public static void main(String[] args) {
        Vehicle v = new Car();
        v.move();
        if (v instanceof Car) {
            Car c = (Car) v;
            c.refuel();
        }
    }
}
